import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
let p;try{p=await import('../helpers/courtesy-touch-coverage-provenance.mjs');}catch(e){if(e.code!=='ERR_MODULE_NOT_FOUND')throw e;}
const read=path=>readFileSync(new URL('../../'+path,import.meta.url));
test('touch coverage admits exactly the reviewed change and reverses all six parent files',()=>{
 assert.ok(p,'touch coverage boundary must exist');
 const m=p.manifest();p.validate(m);
 for(const f of m.files){assert.equal(p.gitBlob(read(f.path)),f.gitBlob);assert.equal(p.gitBlob(p.reverseTapCoverage(f.path,read(f.path))),f.beforeGitBlob);assert.equal(p.gitBlob(p.readBeforeTapCoverage(new URL('../../'+f.path,import.meta.url))),f.beforeGitBlob);assert.throws(()=>p.reverseTapCoverage(f.path,Buffer.concat([read(f.path),Buffer.from('drift')])));}
});
test('touch coverage rejects invented parent bytes, missing rows and altered additions',()=>{
 assert.ok(p);const m=p.manifest();
 for(const change of [x=>x.baseCommit='0'.repeat(40),x=>x.files.pop(),x=>x.files[0].beforeText+='tamper',x=>x.files[0].beforeGitBlob='0'.repeat(40),x=>x.addedPaths.pop(),x=>x.addedFiles.pop()]){const bad=structuredClone(m);change(bad);assert.throws(()=>p.validate(bad));}
 const current=[...m.files.map(f=>f.path),...m.addedPaths,'public/unrelated.mjs'];
 assert.deepEqual(p.inventoryBeforeTapCoverage(current),[...m.files.map(f=>f.path),'public/unrelated.mjs']);
 for(const path of m.addedPaths)assert.throws(()=>p.inventoryBeforeTapCoverage(current.filter(x=>x!==path)));
 for(const f of [...m.files,...m.addedFiles])assert.throws(()=>p.inventoryBeforeTapCoverage(current,{read:path=>path===f.path?Buffer.from('drift'):read(path)}));
 assert.throws(()=>p.inventoryBeforeTapCoverage([...current,current[0]]));
 assert.deepEqual(p.inventoryBeforeTapCoverage(['public/unrelated.mjs']),['public/unrelated.mjs']);
});

// The only live->historical boundary for this touch/layout fix. Runtime tests
// import actual files directly. Never repin any older baseline or manifest.
import {readFileSync as actual} from 'node:fs';
import {createHash} from 'node:crypto';
import {fileURLToPath} from 'node:url';
import {resolve,relative,sep,isAbsolute} from 'node:path';
import assert from 'node:assert/strict';
const root=fileURLToPath(new URL('../../',import.meta.url));
const parent={"commit": "5a9aa4b93f6690c984a00ec8f4f831746d29fae5", "tree": "8b6add423406587449cccc659aea4a8ef6134cf5"};
const previous={
 "public/games/courtesy-contest/game.js": "174fb4477808b7494031e3fb8b503a5685257826",
 "public/games/courtesy-contest/platform.css": "d6f446b31412efabf71a616efc190e760803ee6f",
 "public/games/courtesy-contest/touch-controls.js": "c636c100dcd05f3380d4156ff3562b30c256a529",
 "tests/courtesy-contest/polish-ui.test.mjs": "6a694e78e8a6a23e53dfe44dd7fdd374e98f3e6e",
 "tests/helpers/main-courtesy-help-provenance.mjs": "7cc9d954163a2d7713ed4cb2a8afb86a55b22097",
 "tests/main-courtesy-help-provenance.test.mjs": "6ae5e22c8596db4f2aa2e436a2cad1eab12cdfe2"
};
const added=[
 "docs/courtesy-touch-coverage/MANIFEST.json",
 "tests/helpers/courtesy-touch-coverage-provenance.mjs",
 "tests/courtesy-contest/page-tap-coverage.test.mjs",
 "tests/courtesy-contest/tap-provenance.test.mjs",
 "tests/courtesy-contest/departure-layout.test.mjs"
];
const manifestPath='docs/courtesy-touch-coverage/MANIFEST.json';
export const gitBlob=b=>createHash('sha1').update(`blob ${b.length}\0`).update(b).digest('hex');
export function manifest(){return JSON.parse(actual(new URL('../../'+manifestPath,import.meta.url),'utf8'));}
export function validate(m){
 assert.equal(m.baseCommit,parent.commit);assert.equal(m.baseTree,parent.tree);
 assert.deepEqual(m.files.map(f=>f.path).sort(),Object.keys(previous).sort());
 assert.deepEqual([...m.addedPaths].sort(),[...added].sort());
 assert.deepEqual(m.addedFiles.map(f=>f.path).sort(),added.filter(p=>p!==manifestPath).sort());
 for(const f of m.files){assert.equal(f.beforeGitBlob,previous[f.path]);assert.equal(typeof f.beforeText,'string');assert.equal(gitBlob(Buffer.from(f.beforeText)),f.beforeGitBlob);assert.match(f.gitBlob,/^[a-f0-9]{40}$/);}
 for(const f of m.addedFiles)assert.match(f.gitBlob,/^[a-f0-9]{40}$/);
 return m;
}
export function reverseTapCoverage(path,bytes,m=manifest()){
 validate(m);assert.ok(!m.addedPaths.includes(path),path+' is new touch coverage scope');
 const f=m.files.find(f=>f.path===path);if(!f)return Buffer.from(bytes);
 assert.equal(gitBlob(bytes),f.gitBlob,path+' live drift');return Buffer.from(f.beforeText);
}
export function readBeforeTapCoverage(file,options){
 const absolute=file instanceof URL?fileURLToPath(file):resolve(String(file)),path=relative(root,absolute).split(sep).join('/');
 if(!Object.hasOwn(previous,path)||!path||path==='..'||path.startsWith('../')||isAbsolute(path))return actual(file,options);
 const encoding=typeof options==='string'?options:options?.encoding,bytes=actual(file,typeof options==='object'&&options?{...options,encoding:null}:undefined);
 const before=reverseTapCoverage(path,bytes);return encoding?before.toString(encoding):before;
}
export function inventoryBeforeTapCoverage(paths,{read=p=>actual(new URL('../../'+p,import.meta.url))}={}){
 assert.equal(new Set(paths).size,paths.length,'duplicate touch coverage inventory');const m=validate(manifest());
 if(!paths.some(p=>added.includes(p)))return paths;
 for(const path of added)assert.equal(paths.filter(p=>p===path).length,1,path+' must appear once');
 for(const f of [...m.files,...m.addedFiles])assert.equal(gitBlob(read(f.path)),f.gitBlob,f.path+' live drift');
 return paths.filter(p=>!added.includes(p));
}

// Reconstruct the exact published parent before historical provenance checks.
// Live behavior tests read node:fs directly, never this historical view.
import {readBeforeTapCoverage as actual} from './courtesy-touch-coverage-provenance.mjs';
import {createHash} from 'node:crypto';
import {fileURLToPath} from 'node:url';
import {resolve,relative,sep,isAbsolute} from 'node:path';
import assert from 'node:assert/strict';
const root=fileURLToPath(new URL('../../',import.meta.url));
export const sha256=b=>createHash('sha256').update(b).digest('hex');
export const gitBlob=b=>createHash('sha1').update(`blob ${b.length}\0`).update(b).digest('hex');
const baselineBytes=actual(new URL('../../docs/main-courtesy-help/BASELINE.json',import.meta.url));
assert.equal(sha256(baselineBytes),'30fde790eb5624cd8b47422e2a1314239a681a4e3cee76f60f4f993389123136');
export const baseline=JSON.parse(baselineBytes);
const previous=new Map(baseline.files.map(f=>[f.path,f.gitBlob]));
export function verifyBase(b){
 assert.equal(b.baseCommit,'4be21f0991bf8ae3b6cbf325dc7a7c5b536e18ad');assert.deepEqual(b,baseline);
 const tree={};for(const f of b.files){const parts=f.path.split('/');let dir=tree;for(const name of parts.slice(0,-1))dir=dir[name]??={};assert.ok(!dir[parts.at(-1)],'duplicate remote path');dir[parts.at(-1)]={file:f};}
 function digest(dir){const entries=Object.entries(dir).sort(([a,x],[b,y])=>Buffer.compare(Buffer.from(a+(x.file?'':'/')),Buffer.from(b+(y.file?'':'/'))));const body=Buffer.concat(entries.map(([name,x])=>Buffer.concat([Buffer.from(`${x.file?x.file.mode:'40000'} ${name}\0`),Buffer.from(x.file?x.file.gitBlob:digest(x),'hex')])));return createHash('sha1').update(`tree ${body.length}\0`).update(body).digest('hex');}
 assert.equal(digest(tree),b.baseTree);return true;
}
verifyBase(baseline);
const manifestPath='docs/main-courtesy-help/MANIFEST.json';
let cachedText,cached;
export function manifest(){const text=actual(new URL('../../'+manifestPath,import.meta.url),'utf8');if(text!==cachedText){cachedText=text;cached=JSON.parse(text);}return cached;}
export function validate(m){
 assert.equal(m.baseCommit,baseline.baseCommit);assert.equal(m.baseTree,baseline.baseTree);
 assert.deepEqual(m.files.map(f=>f.path).sort(),baseline.modifiedPaths);assert.deepEqual([...m.addedPaths].sort(),baseline.addedPaths);
 assert.deepEqual(m.addedFiles.map(f=>f.path).sort(),baseline.addedPaths.filter(p=>p!==manifestPath));
 for(const f of m.files){assert.equal(typeof f.beforeText,'string');const bytes=Buffer.from(f.beforeText);assert.equal(f.beforeGitBlob,previous.get(f.path));assert.equal(gitBlob(bytes),f.beforeGitBlob);assert.equal(sha256(bytes),f.beforeSha256);assert.match(f.sha256,/^[a-f0-9]{64}$/);assert.match(f.gitBlob,/^[a-f0-9]{40}$/);}
 return m;
}
export function reverseMainCourtesy(path,bytes,m=manifest()){
 validate(m);assert.ok(!m.addedPaths.includes(path),path+' is new main-courtesy-help scope');const f=m.files.find(f=>f.path===path);if(!f)return Buffer.from(bytes);
 assert.equal(sha256(bytes),f.sha256,path+' current SHA256');assert.equal(gitBlob(bytes),f.gitBlob,path+' current Git blob');return Buffer.from(f.beforeText);
}
export function mainCourtesyParentBytes(path,bytes,m=manifest()){
 validate(m);const f=m.files.find(f=>f.path===path);if(!f)return Buffer.from(bytes);
 const before=Buffer.from(f.beforeText);return before.equals(Buffer.from(bytes))?before:reverseMainCourtesy(path,bytes,m);
}
export function readBeforeMainCourtesy(file,options){
 const absolute=file instanceof URL?fileURLToPath(file):resolve(String(file)),path=relative(root,absolute).split(sep).join('/');
 if(!path||path==='..'||path.startsWith('../')||isAbsolute(path))return actual(file,options);
 const encoding=typeof options==='string'?options:options?.encoding,bytes=actual(file,typeof options==='object'&&options?{...options,encoding:null}:undefined);
 const before=baseline.modifiedPaths.includes(path)?reverseMainCourtesy(path,bytes):bytes;return encoding?before.toString(encoding):before;
}
export function inventoryBeforeMainCourtesy(paths,{read=p=>actual(new URL('../../'+p,import.meta.url)),runtimeOnly=false}={}){
 assert.equal(new Set(paths).size,paths.length,'duplicate main-courtesy-help inventory');const m=validate(manifest());
 if(!paths.some(p=>m.addedPaths.includes(p)))return paths;
 const additions=m.addedPaths.filter(p=>!runtimeOnly||/^(public|worker|src|config)\//.test(p));
 for(const path of additions)assert.equal(paths.filter(p=>p===path).length,1,path+' must appear once');
 for(const f of m.addedFiles.filter(f=>additions.includes(f.path))){const bytes=read(f.path);assert.equal(sha256(bytes),f.sha256,f.path+' added SHA256');assert.equal(gitBlob(bytes),f.gitBlob,f.path+' added Git blob');}
 return paths.filter(p=>!additions.includes(p));
}
